import 'dart:convert';
import 'dart:typed_data';

class SampleImages {
  SampleImages._();

  /// Foto satwa nyata Kupu-kupu Jeruk (Papilio demoleus) yang terbukti valid diuji Gemini API
  static const String butterflyBase64 = '';

  /// Gambar non-satwa Papan Catur yang terbukti ditolak oleh Gemini API (isAnimal: false)
  static const String chessboardBase64 = '';

  static Uint8List get butterflyBytes => base64Decode(butterflyBase64);
  static Uint8List get chessboardBytes => base64Decode(chessboardBase64);
}
